comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[x] for x in reversed(s))
# G-quadruplex (4 runs of G>=3 separated by 1-7 nt)
pat=re.compile(r'(G{3,})(\w{1,7})(G{3,})(\w{1,7})(G{3,})(\w{1,7})(G{3,})')
for m in pat.finditer(seq): print("G4+",m.start()+1,m.end(),m.group())
for m in pat.finditer(rc(seq)):
    s=L-m.end()+1
    print("G4-",s,L-m.start()+1,"(rc)")
# restriction sites
sites={'EcoRI':'GAATTC','BamHI':'GGATCC','HindIII':'AAGCTT','NotI':'GCGGCCGC','XhoI':'CTCGAG',
'SacI':'GAGCTC','PstI':'CTGCAG','KpnI':'GGTACC','SmaI':'CCCGGG','SalI':'GTCGAC','PvuII':'CAGCTG',
'NdeI':'CATATG','BglII':'AGATCT','EcoRV':'GATATC','SpeI':'ACTAGT','XbaI':'TCTAGA'}
print()
for name,s in sites.items():
    hits=[m.start()+1 for m in re.finditer(s,seq)]+[ (L-m.end()+1) for m in re.finditer(rc(s),seq) ]
    if hits: print(name, sorted(hits))
